package hierachicalInheritance;

public class ChildTwo extends ParentClass {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		ChildTwo c= new ChildTwo();
		c.method1();
		c.method2();

	}
	public void method2()
	{
		System.out.println("This is the second child");
	}

}
